#include <sycl/sycl.hpp>
#include <oneapi/math/blas.hpp>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <chrono>
using bf16 = sycl::ext::oneapi::bfloat16;
int main(){
  sycl::queue q{sycl::default_selector_v, sycl::property::queue::in_order{}};
  // classifier-size: out(BT x Vp) = inp(BT x C) x W^T ; m=Vp,n=BT,k=C
  const int BT=256, C=768, Vp=50304;
  bf16* inp = sycl::malloc_shared<bf16>((size_t)BT*C, q);
  bf16* w = sycl::malloc_shared<bf16>((size_t)Vp*C, q);
  float* out = sycl::malloc_shared<float>((size_t)Vp*BT, q);
  srand(42);
  for(int i=0;i<BT*C;i++) inp[i]=bf16((rand()/float(RAND_MAX)-0.5f)*0.1f);
  for(int i=0;i<Vp*C;i++) w[i]=bf16((rand()/float(RAND_MAX)-0.5f)*0.1f);
  // warmup small
  oneapi::math::blas::column_major::gemm(q, oneapi::math::transpose::trans, oneapi::math::transpose::trans,
    (int64_t)Vp,(int64_t)BT,(int64_t)C, 1.0f, w,(int64_t)C, inp,(int64_t)C, 0.0f, out,(int64_t)Vp).wait();
  auto t0=std::chrono::steady_clock::now();
  oneapi::math::blas::column_major::gemm(q, oneapi::math::transpose::trans, oneapi::math::transpose::trans,
    (int64_t)Vp,(int64_t)BT,(int64_t)C, 1.0f, w,(int64_t)C, inp,(int64_t)C, 0.0f, out,(int64_t)Vp).wait();
  auto t1=std::chrono::steady_clock::now();
  double ms = std::chrono::duration<double,std::milli>(t1-t0).count();
  double gflops = 2.0*Vp*BT*C/ms/1e6;
  printf("classifier gemm: %.1f ms (%.1f GFLOPS)\n", ms, gflops);
  // reference check on small sub-block
  double maxdiff=0;
  for(int oc=0; oc<8; oc++){
    for(int bt=0; bt<4; bt++){
      double ref=0; for(int c=0;c<C;c++) ref += (float)inp[bt*C+c]*(float)w[oc*C+c];
      double got = out[oc+bt*(size_t)Vp];
      maxdiff = fmax(maxdiff, fabs(ref-got));
    }
  }
  printf("maxdiff(first block)=%g\n", maxdiff);
  sycl::free(inp,q); sycl::free(w,q); sycl::free(out,q);
  return 0;
}
