  bf16* In = sycl::malloc_shared<bf16>((size_t)BT*C, q);
  bf16* W = sycl::malloc_shared<bf16>((size_t)OC*C, q);
  float* O = sycl::malloc_shared<float>((size_t)OC*BT, q);
  for(int i=0;i<BT*C;i++) In[i]=bf16(0.02f);
