  printf("%s: O[0]=%f expect=%f %s\n", name, O[0], expect, fabs(O[0]-expect)/expect<0.05?"OK":"BAD");
  auto t0=std::chrono::steady_clock::now();
  blas::column_major::gemm(q, transpose::trans, transpose::nontrans, OC,BT,C, 1.0f, W,C, In,C, 0.0f, O,OC).wait();
  auto t1=std::chrono::steady_clock::now();
  printf("  %.1f ms\n", std::chrono::duration<double,std::milli>(t1-t0).count());
  sycl::free(In,q); sycl::free(W,q); sycl::free(O,q);
}
